def section(name,roles):
 global area,role
 area=name;role=roles
def add(id,title,refs,evidence,known,flow,check,status='Saknas',gap='Fält, rättigheter, fel och fullständigt SchoolSoft-flöde behöver verifieras i Testskolan.'):
 items.append(dict(id=id,area=area,title=title,roles=role,sources=refs.split(','),evidence=evidence,schoolsoft=known,proposed_flow=flow,acceptance=check,app_status=status,remaining=gap))
section('01 · Organisation och elevens livscykel','Skoladministratör; rektor; huvudman efter uppdrag')
add('E01','Elevregister och elevsökning','EA,O04','L + M','Elevregister och elevfilter finns.','Sök elev, avgränsa skola och läsår och öppna elevkort med listans urval bevarat.','Två elever med samma namn kan särskiljas; inaktiv elev blir inte en dublett.','Delvis','Sökning och kort finns med exempeldata; identitetskontroll, beständig lagring och inaktiva elever saknas.')
add('E02','Elevkort och sammanhållen översikt','O04','M','Elevkort är en egen ingång.','Samla kontakt, placering, studieplan, grupper och tillåtna dokument på elevkortet med tydliga källor.','En ändring i grupp visas på rätt elevkort; otillåtna dokument avslöjas inte.','Delvis','Kort med utbildning, grupper och sessionshistorik finns; övriga registerkopplingar och behörighet saknas.')
add('E03','Vårdnadshavare och kontaktrelationer','O04,PROFILE','M + K','Vårdnadshavarregister och profiluppgifter förekommer.','Knyt varje kontakt till elev med relation, giltighet, kontaktväg och tillåten insyn.','Kontaktperson och vårdnadshavare förväxlas inte; ändrad relation slår igenom i mottagarlistan.')
add('E04','Skyddade personuppgifter','PROTECT','L','Separat aliasmodul med särskild åtkomst, tvåfaktor och aktivitetslogg beskrivs.','Håll ordinarie elevkort och skyddade uppgifter åtskilda; visa bara den identitet rollen får använda.','Sökning, listor, meddelanden och export röjer inte kopplingen till skyddad identitet.',gap='Modulens aktuella behörigheter, exportregler och logggranskning måste demonstreras med syntetiska uppgifter.')
add('E05','Folkbokföring och uppdatering från SPAR','EA,QUEUE','L + K','Registeruppgifter kan hämtas från folkbokföring.','Visa källa och senaste uppdatering; granska ändrade relationer och adresser innan de skrivs över.','En lokal kontaktuppgift och en skyddad identitet skrivs inte tyst över vid import.')
add('E06','Antagnings- och elevimport','EA,START','L','Import från kö, antagning och andra källor beskrivs.','Välj källa, matcha identiteter, kontrollera dubbletter och granska placeringar innan import bekräftas.','Felaktiga rader får åtgärd; samma fil kan hanteras igen utan dubbla elever.')
add('E07','Inskrivning, placering och skol- eller klassbyte','EA,O04','L + M','Placering i skola och klass ingår.','Ange giltighetsdatum och mottagande klass; visa följder för plan, grupper och åtkomst före beslut.','Framtida placering ändrar inte historisk närvaro. Ett klassbyte ändrar inte program automatiskt.','Delvis','Endast ny exempelpost med vald klass finns; fullständiga byten och datumsatta placeringar saknas.')
add('E08','Avslut, inaktiva elever och återinskrivning','O04,START','M + L','Inaktiva elevkort och inaktivering beskrivs.','Avsluta placering med datum och orsak; bevara åtkomlig historik för rätt roll och erbjud återinskrivning.','Avslutad elev lämnar aktuella grupper utan att betygshistoriken försvinner.')
add('E09','Skolkö och ansökan','EA,QUEUE','L + K','Köansökan skiljs från registrering av barnet.','Visa barnet, sökt skola, årskurs, läsår, status och nästa steg i ett sammanhängande ansökningsflöde.','En sparad barnprofil visas inte som en färdig köansökan.')
add('E10','Platserbjudande, svar och köhistorik','QUEUE','K','Manualen beskriver erbjudande, signerat svar och köhistorik.','Visa svarande, återstående svar, tidsfrist och följd av ja, nej eller ändrat sökår.','Användaren förstår när platsen är accepterad och om ett borttagande påverkar ködatum.',gap='Köregler och krav på flera svar är lokala/versionerade; generalisera dem inte till alla skolor.')
add('E11','Uppsägning av plats','EA','L','E-tjänst för uppsägning beskrivs.','Välj placering och slutdatum; granska följder och ge ett kvitto med faktisk status.','Uppsägning av fritidsplats avslutar inte automatiskt elevens skolplacering.')
add('E12','Klasslistor och kontaktlistor','O04,LOCAL','M + K','Klass- och kontaktlistor är tillgängliga för olika målgrupper.','Välj klass och syfte; låt samma avgränsning styra skärm, utskrift och export.','Elev och vårdnadshavare ser endast tillåtna kontaktfält.','Delvis','Klassfilter och enkel CSV finns; fullständiga listmallar och fältbehörighet saknas.')
section('02 · Program, ämnen och studieplaner','Skoladministratör; SYV; rektor; elev för publicerad plan')
add('P01','Programutbud och programmallar','GYMAR,GYJUN,O04','L + M','Program med ämnesnivåer och schabloner beskrivs.','Välj skolform och utbildningskull; bygg programstruktur med källversion och planerade perioder.','Ändring av en mall skriver inte över redan beslutade individuella avvikelser.')
add('P02','Ämnen, kurser, nivåer och schabloner','GYJUN,O04','L + M','Register och återanvändbara studieinnehåll finns.','Sök kod och benämning; visa Gy11/Gy25 och håll poäng åtskilda från undervisningstid.','Samma benämning med olika regelverk kan inte väljas utan att skillnaden framgår.','Delvis','Exempelbenämningar finns; officiella register, koder och versionsuppdateringar saknas.')
add('P03','Skapa individuella studieplaner','GYMAR,GY,O04','L + M','Studieplan kan skapas individuellt eller för flera elever.','Utgå från rätt programmall, kontrollera urval och avvikelser och skapa separata elevplaner.','En batch med olika kullar får inte fel mall.','Delvis','Visning och terminsutkast finns; komplett utbildningsplan och mallbaserad masskapning saknas.')
add('P04','Individuella val och programanpassningar','GYMAR','R','Markering av anpassat innehåll och borttagna eller ersatta delar aviserades.','Visa obligatoriskt innehåll, individuellt val och avvikelse med orsak och beslutsreferens.','Borttaget innehåll syns i jämförelsen och försvinner inte ur historiken.',gap='Aktuella val, beslutstyper och regeltillämpning måste verifieras per skolform och kull.')
add('P05','Massändring av nivåer och kurser','GYJUN','L','Sidan Nivå-Elever för massuppdatering anges som lanserad.','Filtrera på nivå, period och grupp; granska elevvisa ändringar och avvikelser innan gemensam tillämpning.','En elev med eget upplägg kan undantas utan att urvalet eller skälet går förlorat.')
add('P06','Studieplanens grupp- och schemakoppling','GY,O04','L + M','Studieplaner kopplas till grupper och schema.','Öppna gruppen från planraden; visa ofullständig placering och krockar direkt vid byte.','Planreferens, gruppmedlemskap och elevschema visar samma placering.','Delvis','Sambandet finns inom adminexemplet; giltighetsperioder och koppling till undervisningsvyerna saknas.')
add('P07','Planversion, ändringsorsak och fastställande','GYMAR','Ö','Anteckningsfält är belagda; komplett versions- och beslutsflöde är inte styrkt.','Skilj utkast, granskning och gällande plan; visa författare, orsak och exakt före/efter.','Gammalt utkast kan inte skriva över en nyare gällande plan utan ny granskning.','Delvis','Utkast, jämförelse och konfliktvarning finns; godkännande, fastställande och serverhistorik saknas.')
add('P08','Introduktionsprogram','GYMAR,GYJUN','L','Särskild IM-dokumentation och programstruktur beskrivs.','Samla mål, längd, studieinnehåll, insatser och uppföljning utan att tvinga in IM i nationell standardplan.','Nästa utbildningssteg och elevens individuella mål går att hitta.','Delvis','Exempelmål och slutdatum visas; redigering och fullständig IM-plan saknas.')
add('P09','SYV-dokumentation','GYMAR','R','Eget utrymme för vägledningsdokumentation aviserades.','Dokumentera vägledningsfråga, överenskommelse och nästa steg med tydlig mottagarkrets.','Intern anteckning publiceras inte som standard till alla planläsare.')
add('P10','APL-dokumentation','GYMAR','R','Dokumentation av arbetsplatsförlagt lärande aviserades.','Knyt plats, handledare, period och planerat innehåll till elevens plan och följ upp genomförandet.','Ändrad APL-period synliggör berörda lektioner och ansvariga.',gap='Källan belägger dokumentationsutrymme; avtal, handledarportal och närvarosynk är öppna frågor.')
add('P11','Utbildningskull och blandade regelverk','GYMAR,GYJUN,O04','L + M','Gy11/Gy25 är separerade; blandstudieplan beskrivs uttryckligen för VUX.','Visa elevens regelverk i kontexten och stöd relevanta övergångar med spårbara källversioner.','Stöd beskrivet för VUX antas inte automatiskt gälla gymnasiets alla planbyten.','Delvis','Gy11/Gy25 etiketter finns; övergångsregler och blandplaner saknas.')
add('P12','Programbyte och tillgodoräknat innehåll','O04','Ö','Program och planer är observerade, men programbytesflödet är inte granskat.','Jämför tidigare och nytt program; markera behållet, ersatt och saknat innehåll före ny plan.','Programbyte lämnar ursprungliga resultat och beslut spårbara.')
section('03 · Grupper och medlemskap','Skoladministratör; schemaläggare; mentor')
add('G01','Undervisningsgrupper och läsår','GROUPS,O04','K + M','Ny gruppsida med läsår, filter och massändringar beskrivs.','Skapa grupp för rätt läsår med ämne, ansvarig och giltighet; håll framtida grupper åtskilda från aktiva.','Nästa års grupparbete förändrar inte årets lektioner.','Delvis','Gruppregister med kapacitet finns; skapa/avsluta och läsårshantering saknas.')
add('G02','Elev–grupp och gruppbyte','O04,GROUPS','M + K','Elev-Grupper samt gruppvis masshantering finns som ingångar.','Välj elev eller flera elever, målgrupp och startdatum; granska konsekvens och tillämpa samlat.','Oförenligt innehåll eller full grupp stoppar hela ändringen utan delvis flytt.','Delvis','Batchbyte och modellkontroller finns; datum, ångra och varaktig historik saknas.')
add('G03','Fria grupper','O04','M','Fria grupper skiljs från undervisningsgrupper.','Skapa grupp för exempelvis arbetslag eller aktivitet; visa syftet och vilken åtkomst medlemskapet ger.','Fri grupp tillför inte oavsiktligt kurs, poäng eller betygsrätt.')
add('G04','Klass, samläsning och delgrupper','O04','Ö','Klass och undervisningsgrupp förekommer; komplett samläsningslogik är inte verifierad.','Visa elevernas klasser som information och låt undervisningsgrupper gå över klassgränser.','Samläsande elever dubbelräknas inte i kapacitet, tid eller rapporter.','Delvis','Exempelgrupper omfattar flera klasser; samläsningsplanering och delgruppsregler saknas.')
section('04 · Personal, uppdrag och vikarier','Personaladministratör; schemaläggare; rektor')
add('T01','Personalregister och roll','O04,SUB','M + K','Personal, typ och roll beskrivs.','Hantera person, uppdrag och konto separat med start/slut och ansvarig skola.','Ett avslutat uppdrag stänger relevant åtkomst men förstör inte tidigare undervisningshistorik.')
add('T02','Tjänstefördelning','AI','L','Tjänstefördelning används som underlag till AI Schema.','Knyt lärare och planerad undervisningstid till uppdrag; visa ofördelade timmar och överbelastning.','Poäng, elevtid och personalens arbetstid redovisas med rätt enhet.')
add('T03','Lärarbehörighet och undervisningstid','AI','L','Kontroll av undervisningstid och lämplig lärarbehörighet beskrivs.','Visa behörighetsunderlag, giltighet och planerad tid nära varje uppdrag.','Saknat underlag visas som okänt och får inte felaktigt grönt godkännande.')
add('T04','Korttidsvikarie och tillfällig åtkomst','SUB','K','AcadeMedia beskriver tillfälligt konto med tillgång till ersatt lärares närvaro och planering.','Välj ersatt uppdrag och begränsad period; ge vikarien nödvändiga lektioner och instruktioner.','Åtkomsten upphör vid sluttiden; övriga elevärenden blir inte tillgängliga.',gap='Källans 14-dagarsgräns gäller den beskrivna lösningen 2024; aktuell konfiguration måste verifieras.')
add('T05','Vikariebank, matchning och bokning','SUB','Ö','Tillfällig vikarieåtkomst styrker inte en komplett boknings- eller rekryteringsmodul.','Samla behov, tillgänglighet, kompetens och accepterad bokning; visa olösta pass och reservväg.','Två beställare kan inte boka samma vikarie samtidigt utan en synlig konflikt.')
section('05 · Schema, tid och resurser','Schemaläggare; administratör; rektor; lärare för eget schema')
add('S01','Schemaöversikt och resursfilter','O04','F','Filter för klass, grupp, personal, sal, utrustning och ämne är dokumenterade.','Växla mellan veckoschema och lista, behåll period och urval och öppna passets resurser.','Samma urval ger samma pass i lista och kalender.','Delvis','Veckovy och gruppfilter finns; övriga resursfilter och verkliga perioder saknas.')
add('S02','Skapa, ändra och kopiera lektion','O04','F','Formulär visar dag, ämne, tid, längd, resurser samt Spara och kopiera.','Ange tid och berörda resurser i ett formulär; granska ändring innan den påverkar publicerad vy.','Flera lärare och grupper kan anges där verksamheten kräver det.','Delvis','Befintliga pass kan flyttas och få ny sal/lärare; skapa, kopiera, längdredigering och flervalsresurser saknas.')
add('S03','Perioder, veckor och undantag','O04','F','Lektion har period-, vecko- och undantagsfält.','Visa vilka faktiska datum en regel ger; stöd lov, olika veckor och enstaka undantag.','En inställd lovlektion blir varken planerad undervisningstid eller oanmäld frånvaro.')
add('S04','Salar och utrustning','O04','M','Gemensamt resursregister och schemaval finns.','Registrera kapacitet, tillgänglighet och utrustningsbehov och kontrollera dem vid bokning.','En ledig sal som saknar nödvändig utrustning får inte visas som fullt lämplig.','Delvis','Fasta salar och kapacitet finns; registerredigering, utrustning och tillgänglighet saknas.')
add('S05','Krockar och genomförbarhet','AI','L','AI Schema beskriver genomförbarhetskontroll och dubbelbokningsvarning.','Visa exakt resurs, berörda pass och konfliktens orsak; skilj blockerande fel från önskemål.','Nya eller förvärrade elev-, lärar-, grupp- och lokalkrockar upptäcks.','Delvis','Kontroller finns för exempeldata; transporttid, datumundantag och större regelverk saknas.')
add('S06','Regler och önskemål','AI','L','Skolans villkor och preferenser ingår i schemaunderlaget.','Ange regel, omfattning och prioritet; förklara hur ett önskemål påverkar möjligheten att skapa schema.','Motsägande krav upptäcks före beräkning med väg till berörda regler.')
add('S07','Automatisk schemaläggning','AI','L','SchoolSoft AI Schema är framtaget tillsammans med Royal Schedule.','Skicka validerat underlag till vald motor, följ körningen och jämför förslag med beslutad basversion.','Misslyckad beräkning lämnar publicerat schema tillgängligt.',gap='Ingen optimeringsmotor eller SchoolSoft/Royal-integration är ansluten i vår app.')
add('S08','Förslag till schemakorrigering','AI','L','Notiser och åtgärdsförslag beskrivs.','Visa lösningsalternativ med påverkan på elever, lärare, lokaler och undervisningstid.','Användaren ser vad alternativet löser och vilka nya problem det skapar.')
add('S09','Lokalutnyttjande','AI','L','Optimerad lokalanvändning är en beskriven förmåga.','Visa beläggning per tidsintervall och sal med kapacitet och faktiskt resursbehov.','Full sal skiljs från ledig sal; överkapacitet döljs inte i ett skolgenomsnitt.')
add('S10','Håltimmar och skoldagens längd','AI','L','Minimering av håltimmar är ett beskrivet optimeringsmål.','Jämför elev- och lärarscheman med antal glapp, restid och dagens början/slut.','En förbättring för en grupp får inte presenteras som en förbättring för alla.')
add('S11','Planerad och genomförd undervisningstid','AI,O04','L + M','Garanterad undervisningstid finns som skolledaringång.','Visa tilldelad, schemalagd och faktiskt genomförd tid separat med avvikelsens förklaring.','Inställt och ersatt pass räknas korrekt och poäng används inte som minuter.')
add('S12','Publicera schema och ändringar','AI,O04','L + F','Publicering är ett separat moment efter schemaimport.','Granska version och mottagare; publicera med giltighetstid och visa ändringssammanfattning.','Uppladdat eller redigerat förslag blir inte automatiskt gällande för eleverna.','Delvis','Ändringar syns direkt i adminsessionen; utkast/publicering och gemensamt elevschema saknas.')
add('S13','Schemaimport och källsystem','O04','F','Tidigare vy beskriver Novaschem .nst och Skola24 Procapita .txt i två steg.','Matcha grupper och resurser, kontrollera differens och publicera först efter avstämning.','Ofullständig matchning kan inte tyst ta bort befintliga lektioner.',gap='Format är tidigare lästa instruktioner; import, återföring och aktuell integration behöver verifieras.')
add('S14','Schemautskrift och lektionsrapport','O04','F','Utskrift per klass, grupp, personal, sal och utrustning observerades.','Återanvänd skärmens urval och visa version och giltighet på utskriften.','Rapporten märker utkast tydligt och innehåller samma pass som valt schema.')
